     1	#!/usr/bin/env node
     2	// doctor -> launch -> deliver -> scenarios -> cleanup, in one command.
     3	//   node run.mjs --marker "<str>" --scenario a.mjs [--scenario b.mjs] [--slot N] [--port 9222] [--skip-build]
     4	import path from "node:path";
     5	import { DEFAULT_PORT, parseArgs, releaseLock, resolveWorktree } from "./config.mjs";
     6	import { launch } from "./launch.mjs";
     7	import { deliver } from "./deliver.mjs";
     8	import { loadScenarios, matrixMarkdown, runVerification } from "./harness.mjs";
     9	import { claim } from "../../obsidian-vault/scripts/vault.mjs";
    10	
    11	const args = parseArgs(process.argv.slice(2));
    12	const scenarioFiles = [].concat(args.scenario ?? [], args._);
    13	if (!scenarioFiles.length || !args.marker) {
    14	  console.error("usage: run.mjs --marker <str> --scenario <file.mjs>... [--slot N] [--port 9222] [--skip-build]");
    15	  process.exit(1);
    16	}
    17	
    18	const worktree = path.resolve(args.worktree ?? resolveWorktree());
    19	const port = Number(args.port ?? DEFAULT_PORT);
    20	const t0 = Date.now();
    21	const timings = {};
    22	let session;
    23	
    24	try {
    25	  const scenarios = await loadScenarios(scenarioFiles);
    26	  // Only claims a free vault; exits 2 with candidates when the user must pick one to take over.
    27	  if (args.slot === undefined) await claim({ worktree });
    28	  session = await launch({ worktree, slot: args.slot, port });
    29	  const { client, vault, branch, action } = session;
    30	  timings.launchMs = session.ms;
    31	  console.log(`launch: ${action} (Obsidian was ${session.obsidianBefore}) -> ${vault.name}${vault.slot ? ` [slot ${vault.slot}]` : " [leased]"}`);
    32	
    33	  const delivered = await deliver({ worktree, vault, client, marker: args.marker, skipBuild: !!args["skip-build"] });
    34	  timings.deliverMs = delivered.ms;
    35	  for (const w of delivered.watchers) console.warn(`WARN competing watcher: ${w}`);
    36	  console.log(`deliver: built + reloaded ${delivered.pluginId}, marker found (${delivered.ms}ms)`);
    37	
    38	  const runStamp = new Date().toISOString().replace(/[:.]/g, "-").slice(0, 19);
    39	  const artifactsDir = path.join(worktree, "local", "obsidian-cdp", "artifacts", branch.replace(/\//g, "-"), runStamp);
    40	  const hStart = Date.now();
    41	  const { lastRun, lastRunPath } = await runVerification({
    42	    client,
    43	    vault,
    44	    branch,
    45	    scenarios,
    46	    artifactsDir,
    47	    meta: { runStamp, marker: args.marker, launchAction: action, obsidianBefore: session.obsidianBefore, bundleSha: delivered.bundleSha, timings },
    48	  });
    49	  timings.scenariosMs = Date.now() - hStart;
    50	  timings.totalMs = Date.now() - t0;
    51	
    52	  console.log(`\nlast-run.json: ${lastRunPath}`);
    53	  console.log(`timings: ${JSON.stringify(timings)}\n`);
    54	  console.log(matrixMarkdown(lastRun.results));
    55	  const shots = lastRun.results.filter((r) => r.screenshot);
    56	  console.log("\npr-evidence args:");
    57	  console.log(shots.map((r) => `${JSON.stringify(r.screenshot)}=${JSON.stringify(r.scenario)}`).join(" \\\n"));
    58	  process.exitCode = lastRun.pass ? 0 : 1;
    59	} catch (error) {
    60	  console.error(error.message);
    61	  if (error.candidates) console.log(JSON.stringify({ candidates: error.candidates }, null, 2));
    62	  process.exitCode = error.exitCode ?? 1;
    63	} finally {
    64	  if (session) {
    65	    session.client.close();
    66	    releaseLock(session.vault.lockFile);
    67	  }
    68	}
