     1	// Worktree, vault slot and lock resolution shared by every script.
     2	import { execFileSync } from "node:child_process";
     3	import { existsSync, readFileSync, readdirSync, writeFileSync, rmSync } from "node:fs";
     4	import os from "node:os";
     5	import path from "node:path";
     6	import { leasedVault } from "../../obsidian-vault/scripts/vault.mjs";
     7	
     8	export const VAULT_SCRIPT = path.join(os.homedir(), ".claude", "skills", "obsidian-vault", "scripts", "vault.mjs");
     9	
    10	export const DEFAULT_PORT = 9222;
    11	export const OBSIDIAN_APP = "/Applications/Obsidian.app";
    12	
    13	export const parseArgs = (argv) => {
    14	  const out = { _: [] };
    15	  for (let i = 0; i < argv.length; i++) {
    16	    const arg = argv[i];
    17	    if (!arg.startsWith("--")) {
    18	      out._.push(arg);
    19	      continue;
    20	    }
    21	    const [key, inline] = arg.slice(2).split("=", 2);
    22	    const next = argv[i + 1];
    23	    const value = inline ?? (next && !next.startsWith("--") ? (i++, next) : true);
    24	    out[key] = key in out ? [].concat(out[key], value) : value;
    25	  }
    26	  return out;
    27	};
    28	
    29	const git = (cwd, ...args) =>
    30	  execFileSync("git", ["-C", cwd, ...args], { encoding: "utf8" }).trim();
    31	
    32	export const resolveWorktree = (from = process.cwd()) => git(from, "rev-parse", "--show-toplevel");
    33	
    34	export const resolveBranch = (worktree) =>
    35	  git(worktree, "branch", "--show-current") || git(worktree, "rev-parse", "--short", "HEAD");
    36	
    37	// Reads one key only, so no other .env value is ever loaded or printed.
    38	const readEnvKey = (file, key) => {
    39	  if (!existsSync(file)) return undefined;
    40	  const line = readFileSync(file, "utf8")
    41	    .split("\n")
    42	    .find((l) => l.trim().startsWith(`${key}=`));
    43	  if (!line) return undefined;
    44	  let value = line.slice(line.indexOf("=") + 1).trim();
    45	  if (/^(['"]).*\1$/.test(value)) value = value.slice(1, -1);
    46	  return value;
    47	};
    48	
    49	const parseVaultList = (raw) => {
    50	  if (!raw) return [];
    51	  try {
    52	    const parsed = JSON.parse(raw);
    53	    return (Array.isArray(parsed) ? parsed : [parsed]).map(String);
    54	  } catch {
    55	    return raw.split(",").map((s) => s.trim()).filter(Boolean);
    56	  }
    57	};
    58	
    59	const readManifestId = (dir) => {
    60	  const file = path.join(dir, "manifest.json");
    61	  return existsSync(file) ? JSON.parse(readFileSync(file, "utf8")).id : undefined;
    62	};
    63	
    64	// Entries may be plugin dirs (".../.obsidian/plugins/<folder>") or plain vault roots.
    65	const resolveEntry = (entry, pluginId) => {
    66	  const idx = entry.indexOf("/.obsidian");
    67	  if (idx !== -1) return { root: entry.slice(0, idx), pluginDir: entry.replace(/\/$/, "") };
    68	  const root = entry.replace(/\/$/, "");
    69	  const pluginsDir = path.join(root, ".obsidian", "plugins");
    70	  const folder = existsSync(pluginsDir)
    71	    ? readdirSync(pluginsDir).find((f) => readManifestId(path.join(pluginsDir, f)) === pluginId)
    72	    : undefined;
    73	  if (!folder) throw new Error(`No plugin folder with id ${pluginId} under ${pluginsDir}`);
    74	  return { root, pluginDir: path.join(pluginsDir, folder) };
    75	};
    76	
    77	// No --slot: use this worktree's obsidian-vault lease, so CDP runs land in the vault its watcher builds into.
    78	const resolveLeased = (worktree) => {
    79	  const vault = leasedVault({ worktree });
    80	  if (!vault)
    81	    throw Object.assign(
    82	      new Error(`No vault leased to ${worktree}. Run: node ${VAULT_SCRIPT} claim --worktree ${worktree}`),
    83	      { exitCode: 2 },
    84	    );
    85	  return {
    86	    slot: null,
    87	    root: vault.root,
    88	    name: vault.name,
    89	    pluginDir: vault.pluginDir,
    90	    pluginFolder: path.basename(vault.pluginDir),
    91	    pluginId: readManifestId(path.join(worktree, "apps", "obsidian")),
    92	    lockFile: path.join(vault.root, ".obsidian", "dg-verify.lock"),
    93	  };
    94	};
    95	
    96	export const resolveSlot = ({ worktree, slot }) => {
    97	  if (slot === undefined) return resolveLeased(worktree);
    98	  const envFile = path.join(worktree, "apps", "obsidian", ".env");
    99	  const entries = parseVaultList(readEnvKey(envFile, "OBSIDIAN_VERIFY_VAULTS"));
   100	  if (!entries.length) throw new Error(`OBSIDIAN_VERIFY_VAULTS missing in ${envFile}`);
   101	  const n = Number(slot);
   102	  if (!(n >= 1 && n <= entries.length))
   103	    throw new Error(`--slot ${slot} out of range (1..${entries.length})`);
   104	  const pluginId = readManifestId(path.join(worktree, "apps", "obsidian"));
   105	  const { root, pluginDir } = resolveEntry(entries[n - 1], pluginId);
   106	  return {
   107	    slot: n,
   108	    slotCount: entries.length,
   109	    root,
   110	    name: path.basename(root),
   111	    pluginDir,
   112	    pluginFolder: path.basename(pluginDir),
   113	    pluginId,
   114	    lockFile: path.join(root, ".obsidian", "dg-verify.lock"),
   115	  };
   116	};
   117	
   118	export const isPidAlive = (pid) => {
   119	  try {
   120	    process.kill(pid, 0);
   121	    return true;
   122	  } catch (error) {
   123	    return error.code === "EPERM";
   124	  }
   125	};
   126	
   127	export const readLock = (lockFile) => {
   128	  if (!existsSync(lockFile)) return null;
   129	  try {
   130	    const lock = JSON.parse(readFileSync(lockFile, "utf8"));
   131	    return { ...lock, alive: isPidAlive(lock.pid), self: lock.pid === process.pid };
   132	  } catch {
   133	    return { corrupt: true, alive: false };
   134	  }
   135	};
   136	
   137	export const acquireLock = ({ lockFile, branch }) => {
   138	  const lock = readLock(lockFile);
   139	  if (lock?.alive && !lock.self)
   140	    throw new Error(`Vault locked by pid ${lock.pid} (${lock.branch}); use another --slot`);
   141	  writeFileSync(
   142	    lockFile,
   143	    JSON.stringify({ pid: process.pid, branch, startedAt: new Date().toISOString() }),
   144	  );
   145	};
   146	
   147	// Only removes a lock this process owns.
   148	export const releaseLock = (lockFile) => {
   149	  if (readLock(lockFile)?.self) rmSync(lockFile);
   150	};
   151	
   152	export const slugify = (s) =>
   153	  s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "").slice(0, 60);
