     1	#!/usr/bin/env node
     2	// Gets Obsidian onto the debug port with the slot vault open, then takes the vault lock.
     3	//   node launch.mjs [--slot N] [--port 9222] [--worktree <path>]
     4	import { spawnSync } from "node:child_process";
     5	import { pathToFileURL } from "node:url";
     6	import { DEFAULT_PORT, OBSIDIAN_APP, acquireLock, parseArgs, resolveWorktree } from "./config.mjs";
     7	import { doctor, obsidianPids, probePort } from "./doctor.mjs";
     8	import { connect } from "./driver.mjs";
     9	
    10	const run = (cmd, args) => {
    11	  const res = spawnSync(cmd, args, { encoding: "utf8" });
    12	  if (res.status !== 0) throw new Error(`${cmd} ${args.join(" ")} failed: ${res.stderr.trim()}`);
    13	};
    14	
    15	const until = async (check, { timeout, label }) => {
    16	  const deadline = Date.now() + timeout;
