import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const PAGE_TITLE = "Trang test/";
const SLOTS = ["1", "2", "3"] as const;

type Item = { caption: string; url: string; blockUid: string };
type Upload = { name: string; caption: string; base64: string };
type Result = {
  page: string;
  pageUid: string;
  branchBlockUid: string;
  runBlockUid: string;
  items: Item[];
};
// Minimal shapes of the worktree's roamSession exports; typed imports can't use a runtime path.
type Session = { page: PlaywrightPage; close: () => Promise<void> };
type PlaywrightPage = {
  waitForFunction: (fn: string, arg?: unknown, opts?: { timeout: number }) => Promise<unknown>;
  evaluate: <R, A>(fn: (arg: A) => R | Promise<R>, arg: A) => Promise<R>;
  waitForTimeout: (ms: number) => Promise<void>;
};
type RoamSessionModule = {
  openRoamSession: (opts: { slot: string; timeout?: number }) => Promise<Session>;
  resolveSlotConfig: (opts: { slot: string }) => unknown;
};

const git = (args: string[]): string =>
  execFileSync("git", args, { encoding: "utf8" }).trim();

const parseCli = (
  argv: string[],
): { flags: Record<string, string>; files: string[] } => {
  const flags: Record<string, string> = {};
  const files: string[] = [];
  for (let i = 0; i < argv.length; i += 1) {
    if (argv[i].startsWith("--")) flags[argv[i].slice(2)] = argv[++i] ?? "";
    else files.push(argv[i]);
  }
  return { flags, files };
};

const toUpload = (spec: string): Upload & { file: string } => {
  const eq = spec.indexOf("=");
  const file = path.resolve(eq === -1 ? spec : spec.slice(0, eq));
  if (!fs.existsSync(file)) throw new Error(`No such file: ${file}`);
  const name = path.basename(file);
  const caption =
    eq === -1 ? name.replace(/\.[^.]+$/, "") : spec.slice(eq + 1).trim();
  return { file, name, caption, base64: fs.readFileSync(file).toString("base64") };
};

const loadRoamSession = async (root: string): Promise<RoamSessionModule> => {
  const mod = await import(path.join(root, "apps/roam/scripts/playwright/roamSession.ts"));
  return (mod.openRoamSession ? mod : mod.default) as RoamSessionModule;
};

const isProfileLock = (error: unknown): boolean =>
  error instanceof Error && /profile is already in use/i.test(error.message);

