   126	    const entry = byWorktree.get(worktree) ?? { worktree, pids: [], vaults: new Set() };
   127	    entry.pids.push(pid);
   128	    for (const v of vaults) if (mirror.includes(v.pluginDir)) entry.vaults.add(v.name);
