   134	const readCdpLock = (root) => {
   135	  const file = path.join(root, ".obsidian", "dg-verify.lock");
   136	  if (!existsSync(file)) return null;
   137	  try {
   138	    const lock = JSON.parse(readFileSync(file, "utf8"));
   139	    return isPidAlive(lock.pid) ? lock : null;
   140	  } catch {
   141	    return null;
   142	  }
   143	};
