   145	// Leases whose worktree was deleted free themselves; nothing else expires.
   146	const pruneLeases = (reg) => {
   147	  for (const [name, lease] of Object.entries(reg.leases))
   148	    if (!existsSync(lease.worktree) || !reg.vaults.some((v) => v.name === name)) delete reg.leases[name];
   149	};
