   151	export const describe = (reg) => {
   152	  pruneLeases(reg);
   153	  const watchers = scanWatchers(reg.vaults);
   154	  return reg.vaults.map((v) => {
   155	    const lease = reg.leases[v.name] ?? null;
   156	    const vWatchers = watchers.filter((w) => w.vaults.includes(v.name));
   157	    const cdp = readCdpLock(v.root);
   158	    const state = vWatchers.length || cdp ? "live" : lease ? "idle" : "free";
   159	    return { ...v, state, lease: lease && { ...lease, currentBranch: currentBranch(lease.worktree) }, watchers: vWatchers, cdp };
   160	  });
   161	};
   162	
   163	const stopWatchers = (watchers) => {
   164	  for (const w of watchers)
   165	    for (const pid of w.pids) {
   166	      try {
   167	        process.kill(pid, "SIGTERM");
   168	      } catch {}
   169	    }
   170	};
   171	
   172	const leaseFor = (states, worktree, db) => states.find((s) => s.lease?.worktree === worktree && s.db === db);
