   174	export const claim = async ({ worktree, db = "local", take }) =>
   175	  withRegistry((reg) => {
   176	    const states = describe(reg);
   177	    const branch = currentBranch(worktree);
   178	    const others = (s) => s.watchers.filter((w) => w.worktree !== worktree);
   179	    const grant = (s) => {
   180	      const prev = leaseFor(states, worktree, db);
   181	      if (prev && prev.name !== s.name) delete reg.leases[prev.name];
   182	      if (s.lease && s.lease.worktree !== worktree) clearEnvIfPointsAt(s.lease.worktree, s);
   183	      reg.leases[s.name] = { worktree, branch, claimedAt: new Date().toISOString() };
   184	      syncEnv(worktree, s);
   185	      return { ...s, lease: reg.leases[s.name] };
   186	    };
   187	    // A watcher reads .env once at startup, so one aimed elsewhere keeps building there until restarted.
   188	    const staleWatchers = (s) => scanWatchers(reg.vaults).filter((w) => w.worktree === worktree && !w.vaults.includes(s.name));
   189	    const result = (r) => {
   190	      const stale = staleWatchers(r.vault);
   191	      return stale.length ? { ...r, restartWatcher: `pids ${stale.flatMap((w) => w.pids).join(",")} still build elsewhere; restart pnpm dev` } : r;
   192	    };
   193	
   194	    if (take) {
   195	      const target = states.find((s) => s.name === take);
   196	      if (!target) throw exitError(`unknown vault ${take}; pool: ${states.map((s) => s.name).join(", ")}`, 1);
   197	      if (target.db !== db) throw exitError(`${take} is a ${target.db}-db vault; pass --db ${target.db}`, 1);
   198	      if (target.cdp && target.cdp.branch !== branch)
   199	        throw exitError(`${take} has a CDP run in progress (pid ${target.cdp.pid}, ${target.cdp.branch}); wait for it`, 1);
   200	      stopWatchers(others(target));
   201	      return result({ action: "took-over", from: target.lease?.branch ?? null, stopped: others(target).flatMap((w) => w.pids), vault: grant(target) });
   202	    }
   203	
   204	    const mine = leaseFor(states, worktree, db);
   205	    if (mine) {
   206	      syncEnv(worktree, mine);
   207	      return result({ action: "reused", vault: mine, conflicts: others(mine) });
   208	    }
   209	
   210	    const free = states.find((s) => s.db === db && !s.lease && !s.cdp && !others(s).length);
   211	    if (free) return result({ action: "claimed", vault: grant(free) });
   212	
   213	    const candidates = states
   214	      .filter((s) => s.db === db)
   215	      .map((s) => ({
   216	        vault: s.name,
   217	        state: s.state,
   218	        holder: s.lease?.currentBranch ?? s.watchers[0]?.worktree ?? null,
   219	        worktree: s.lease?.worktree ?? s.watchers[0]?.worktree ?? null,
   220	        since: s.lease?.claimedAt ?? null,
   221	        cdpRun: Boolean(s.cdp),
   222	      }));
   223	    throw exitError(
   224	      `No free ${db}-db vault. Ask the user which one ${branch} may take over (idle = leased, nothing running; ` +
   225	        `live = a watcher or CDP run is using it and will be stopped), then rerun with --take <vault>.`,
   226	      2,
   227	      { candidates },
   228	    );
   229	  });
