   231	export const release = async ({ worktree, db }) =>
   232	  withRegistry((reg) => {
   233	    const states = describe(reg);
   234	    const released = [];
   235	    for (const s of states) {
   236	      if (s.lease?.worktree !== worktree || (db && s.db !== db)) continue;
   237	      stopWatchers(s.watchers.filter((w) => w.worktree === worktree));
   238	      clearEnvIfPointsAt(worktree, s);
   239	      delete reg.leases[s.name];
   240	      released.push(s.name);
   241	    }
   242	    return { released };
   243	  });
