   280	    s.db,
   281	    s.state,
   282	    s.lease ? s.lease.currentBranch : "-",
   283	    s.watchers.map((w) => (s.lease?.worktree === w.worktree ? `pid ${w.pids[0]}` : `pid ${w.pids[0]} (${path.basename(w.worktree)}, unleased)`)).join("; ") || "-",
   284	    s.cdp ? `cdp pid ${s.cdp.pid}` : "-",
