   293	  for (let i = 0; i < argv.length; i++) {
   294	    if (!argv[i].startsWith("--")) out._.push(argv[i]);
   295	    else out[argv[i].slice(2)] = argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[++i] : true;
